const _dayDiff = (a, b) => Math.round((Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 86400000);

// data = CREATIVE_SQL result, end = ISO date
const analyzeCreative = (data, end) => {
  const names = {};
